private const ALLOWED = ['image/jpeg', 'image/png'];

public function save(array $file): string
{
    $finfo = new finfo(FILEINFO_MIME_TYPE);
    $mime = $finfo->file($file['tmp_name']);
    if (!in_array($mime, self::ALLOWED, true)) {
        throw new RuntimeException('unsupported type');
    }

    $dest = $this->dir . '/' . $file['name'];
    move_uploaded_file($file['tmp_name'], $dest);

    return $dest;
}

private const EXTENSIONS = ['image/jpeg' => '.jpeg', 'image/png' => '.png'];

$dest = $this->dir . '/' . bin2hex(random_bytes(16)) . self::EXTENSIONS[$mime];
if (!move_uploaded_file($file['tmp_name'], $dest)) {
    throw new RuntimeException('move failed');
}

return $dest;

if (($file['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK) {
    throw new RuntimeException('upload failed');
}
if ($file['size'] > 2 * 1024 * 1024) {
    throw new RuntimeException('too large');
}
if (!is_uploaded_file($file['tmp_name'])) {
    throw new RuntimeException('not an upload');
}

$base = realpath($this->dir);
if ($base === false) {
    throw new RuntimeException('bad directory');
}

$dest = $base . '/' . bin2hex(random_bytes(16)) . self::EXTENSIONS[$mime];
if (!str_starts_with($dest, $base . '/')) {
    throw new RuntimeException('path escaped the directory');
}
